26: export const COMPLETION_XP = 100;
27: export const WIN_XP = 50;
28: export const PODIUM_XP = 25;
29: export const HOLE_IN_ONE_XP = 20;
30: export const BIRDIE_XP = 10;
31: export const PODIUM_MIN_PLAYERS = 4;
