36: export function calculateMatchReward(input: MatchRewardInput): MatchReward {
37:   const rank = count(input.rank);
38:   const playerCount = count(input.playerCount);
39:   const win = rank === 1 ? WIN_XP : 0;
40:   const onPodium = (rank === 2 || rank === 3) && playerCount >= PODIUM_MIN_PLAYERS;
41:   const podium = win === 0 && onPodium ? PODIUM_XP : 0;
42:   const holesInOne = count(input.holesInOne) * HOLE_IN_ONE_XP;
43:   const birdies = count(input.birdies) * BIRDIE_XP;
44:   const breakdown = { completion: COMPLETION_XP, win, podium, holesInOne, birdies };
45:   const total = breakdown.completion + breakdown.win + breakdown.podium + breakdown.holesInOne + breakdown.birdies;
46:   return { xp: Math.max(0, Math.round(total)), breakdown };
47: }
