49: export function applyMatchStatistics(stats: PlayerStatistics, input: MatchRewardInput): PlayerStatistics {
50:   const rank = count(input.rank);
51:   const holesPlayed = count(input.holesPlayed);
52:   const holesCompleted = count(input.holesCompleted);
53:   const totalStrokes = count(input.totalStrokes);
54:   const holesInOne = count(input.holesInOne);
55:   const duration = Math.max(0, Math.round(finite(input.durationSeconds)));
56:   const previousBest =
57:     typeof stats.bestRoundStrokes === 'number' && Number.isFinite(stats.bestRoundStrokes)
58:       ? stats.bestRoundStrokes
59:       : null;
60:   const fullRound = holesPlayed > 0 && holesCompleted === holesPlayed;
61:   const bestRoundStrokes = fullRound
62:     ? previousBest === null
63:       ? totalStrokes
64:       : Math.min(previousBest, totalStrokes)
65:     : previousBest;
66:   return {
67:     matchesPlayed: count(stats.matchesPlayed) + 1,
68:     matchesWon: count(stats.matchesWon) + (rank === 1 ? 1 : 0),
69:     holesPlayed: count(stats.holesPlayed) + holesPlayed,
70:     holesCompleted: count(stats.holesCompleted) + holesCompleted,
71:     totalStrokes: count(stats.totalStrokes) + totalStrokes,
72:     holesInOne: count(stats.holesInOne) + holesInOne,
73:     bestRoundStrokes,
74:     totalPlayTimeSeconds: count(stats.totalPlayTimeSeconds) + duration,
75:   };
76: }
